/// Dash. Cost 2. Gain 10 block + Deal 10 damage.
pub(crate) fn play_dash(state: &mut CombatState, target: Option<CreatureUid>) -> EffectResult {
    let t = target.expect("Dash: Enemy-targeted");
    // C# `Dash.OnPlay` (v0.107.1 Dash.cs:30-33) gains block FIRST via
    // `CreatureCmd.GainBlock`, THEN executes `DamageCmd.Attack`. The order
    // is load-bearing: the player must already hold Dash's block before the
    // targeted attack fires, so any on-attack-received retaliation (e.g. a
    // Thorns enemy) is absorbed by that block instead of landing on bare HP.
    gain_block_player(state, current_card_block(state));
    let base = current_card_damage(state);
    let _ = deal_damage_player_to_enemy(state, t, base);
    EffectResult::Resolved
}

